// 1. Check if we actually have a response body
if (!pw.response.body) {
    console.error("No response body found!");
} else {
    try {
        //const resp = JSON.parse(pw.response.body);
        
        // 2. Check if the token is actually there
        if (pw.response.body && pw.response.body.access_token) {
            pw.env.set("bearerToken", pw.response.body.access_token);
            console.log("Token updated!");
        } else {
            console.log("JSON received, but no access_token found.");
        }
    } catch (e) {
        console.error("Failed to parse JSON: " + e.message);
    }
}

// 3. Simple test that SHOULD always show up
pw.test("Script check", () => {
    pw.expect(pw.response.status).toBe(200);
});

